INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G1.SOCIAL.CLEANING_MY_BODY.BODY_CLEANING', 'ENVI.G1.SOCIAL.CLEANING_MY_BODY', 'environmental_activities', 1, 'Identify materials used to clean different parts of the body', ARRAY['ENVI.G1.SOCIAL.CLEANING_MY_BODY.a']::text[], 'Names materials for cleaning each body part: water and soap for hands, face, feet and body; a toothbrush with toothpaste or a chewing stick (mswaki) for teeth; a comb or brush and soap for hair; a towel to dry; a nail cutter for nails; and says why we keep the body clean. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G1.RUBRIC.1.1), never as a phone question: b) wash face, teeth, hands, feet, and hair using locally available materials.', '["picture: what do we clean this part with","match material to body part","odd one out"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G1.SOCIAL.OUR_HOME.HOME_CLEANING', 'ENVI.G1.SOCIAL.OUR_HOME', 'environmental_activities', 1, 'Identify materials used to clean the home', ARRAY['ENVI.G1.SOCIAL.OUR_HOME.a']::text[], 'Names materials used to clean a home: a broom (fagio) to sweep, a dustpan and a litter bin to collect litter, a cloth or duster to wipe and dust, a mop or rag with water to clean the floor, soap and water, a rake for the compound. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G1.RUBRIC.1.1), never as a phone question: c) carry out activities to ensure cleanliness in the home.', '["what is used to sweep, wipe, dust","match tool and job","odd one out"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G1.SOCIAL.OUR_HOME.HOME_ACCIDENTS', 'ENVI.G1.SOCIAL.OUR_HOME', 'environmental_activities', 1, 'State common accidents at home for personal and others'' safety', ARRAY['ENVI.G1.SOCIAL.OUR_HOME.b']::text[], 'States common accidents at home (burns from fire, hot water or a jiko; cuts from knives and broken glass; falls from stairs, trees or wet floors; poisoning from medicines or paraffin; electric shocks from sockets) and the safe thing to do: keep away, never touch, tell an adult. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception.', '["what could happen here","safe or not safe","what to do"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G1.SOCIAL.FAMILY_NEEDS.BASIC_NEEDS', 'ENVI.G1.SOCIAL.FAMILY_NEEDS', 'environmental_activities', 1, 'Identify and classify the basic needs of a family', ARRAY['ENVI.G1.SOCIAL.FAMILY_NEEDS.a', 'ENVI.G1.SOCIAL.FAMILY_NEEDS.b']::text[], 'Identifies the basic needs of a family (food, water, clothing, shelter) and classifies items and structures as basic needs: a house, hut or manyatta as shelter; a shirt, dress or blanket as clothing; ugali, beans or milk as food. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception.', '["is this a basic need","which need is this","sort into food, shelter, clothing"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G1.SOCIAL.FAMILY_NEEDS.FOOD_SOURCES', 'ENVI.G1.SOCIAL.FAMILY_NEEDS', 'environmental_activities', 1, 'Group food eaten at home into food from plants and food from animals, and choose suitable food for a healthy body', ARRAY['ENVI.G1.SOCIAL.FAMILY_NEEDS.c', 'ENVI.G1.SOCIAL.FAMILY_NEEDS.d']::text[], 'Sorts food eaten at home into food from plants (maize, beans, sukuma wiki, bananas, rice, potatoes, fruits) and food from animals (milk, eggs, meat, fish), and selects suitable food for a healthy body (fruits, vegetables, milk, githeri, clean water) over too many sweets, crisps and sodas. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception.', '["from a plant or an animal","which food is healthy","which plate is better"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G1.SOCIAL.OUR_SCHOOL.HOME_SCHOOL_FEATURES', 'ENVI.G1.SOCIAL.OUR_SCHOOL', 'environmental_activities', 1, 'Identify the main physical features between home and school', ARRAY['ENVI.G1.SOCIAL.OUR_SCHOOL.a']::text[], 'Names the main physical features between home and school (roads and paths, rivers and bridges, hills and valleys, big trees, churches and mosques, shops, a market, a dispensary) and uses them to say where a place is. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G1.RUBRIC.1.1), never as a phone question: b) draw main physical features between home and school.', '["what do you pass on the way","is this a feature","natural or made by people"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G1.SOCIAL.OUR_SCHOOL.WAY_SAFETY', 'ENVI.G1.SOCIAL.OUR_SCHOOL', 'environmental_activities', 1, 'Say how to keep safe on the way to school', ARRAY['ENVI.G1.SOCIAL.OUR_SCHOOL.c']::text[], 'Says how to keep safe on the way to and from school: walk with friends or an adult, walk on the side of the road facing oncoming cars, cross at a crossing after looking both ways, go straight home, do not play on the road or near rivers, never go with or take things from strangers, tell a trusted adult if afraid. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception.', '["safe or unsafe","what to do here","where to walk"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G1.SOCIAL.OUR_MARKET.MARKET_PEOPLE', 'ENVI.G1.SOCIAL.OUR_MARKET', 'environmental_activities', 1, 'Identify the roles of people found in a market', ARRAY['ENVI.G1.SOCIAL.OUR_MARKET.a']::text[], 'Names people in a market and their roles: sellers (traders) sell goods, buyers buy, porters and handcart pullers carry goods, boda boda and lorry drivers transport goods, cleaners clean, market masters or county askaris keep order and collect fees, butchers sell meat. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception.', '["who is this person in the market","what does this person do","match person and job"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G1.SOCIAL.OUR_MARKET.FRUIT_VEG', 'ENVI.G1.SOCIAL.OUR_MARKET', 'environmental_activities', 1, 'List food items found in a market and sort them into fruits and vegetables', ARRAY['ENVI.G1.SOCIAL.OUR_MARKET.b', 'ENVI.G1.SOCIAL.OUR_MARKET.c']::text[], 'Lists food items found in a local market (maize, beans, potatoes, tomatoes, onions, sukuma wiki, cabbage, bananas, mangoes, oranges, pawpaws, avocados, fish, meat, eggs) and sorts fruits (mangoes, oranges, bananas, pawpaws, pineapples, avocados, passion fruit) from vegetables (sukuma wiki, cabbage, spinach, carrots, onions, managu, terere). Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception.', '["fruit or vegetable","name a food sold in the market","odd one out"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G1.NATURA.WEATHER_AND_THE_SKY.SKY', 'ENVI.G1.NATURA.WEATHER_AND_THE_SKY', 'environmental_activities', 1, 'Describe the appearance of the sky during the day and at night', ARRAY['ENVI.G1.NATURA.WEATHER_AND_THE_SKY.a']::text[], 'Describes the day sky (bright, blue or cloudy, the sun, clouds, birds, sometimes the moon) and the night sky (dark, the moon, stars, sometimes clouds), and knows the sun is not seen at night and stars are too faint to see in the day. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception.', '["day or night sky","what do we see in the sky now","which is seen at night"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G1.NATURA.WEATHER_AND_THE_SKY.WEATHER_KINDS', 'ENVI.G1.NATURA.WEATHER_AND_THE_SKY', 'environmental_activities', 1, 'Identify weather conditions in the locality', ARRAY['ENVI.G1.NATURA.WEATHER_AND_THE_SKY.b']::text[], 'Identifies weather conditions (sunny, rainy, cloudy, windy, hot, cold) from the sky, pictures and symbols, and says what people do or wear in each (an umbrella for rain, a sweater for cold, a hat for sun). Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G1.RUBRIC.2.1), never as a phone question: c) record different weather conditions in the locality.', '["what is the weather in the picture","match weather to symbol","what do we wear"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G1.NATURA.SOIL.SOIL_PLAY', 'ENVI.G1.NATURA.SOIL', 'environmental_activities', 1, 'Identify ways of playing with soil for enjoyment and safely', ARRAY['ENVI.G1.NATURA.SOIL.a']::text[], 'Names ways of playing with soil (filling and emptying cans, building sand castles, modelling pots, animals and balls, drawing in the soil, painting with soil mixed with water, making mud patterns) and the safe rules: never eat soil, keep it away from eyes, wash hands after playing. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G1.RUBRIC.2.1), never as a phone question: b) play with soil for enjoyment; c) model objects using soil at school.', '["which is a way of playing with soil","what can we make","what to do after playing"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G1.NATURA.SOUND.SOUNDS', 'ENVI.G1.NATURA.SOUND', 'environmental_activities', 1, 'Identify sounds in the environment and tell sounds that warn of danger', ARRAY['ENVI.G1.NATURA.SOUND.a', 'ENVI.G1.NATURA.SOUND.c']::text[], 'Identifies sounds from people (talking, singing, clapping), animals (a cow mooing, a dog barking, a cock crowing), machines (a car, a motorbike, a grinding mill) and nature (rain, thunder, wind), and tells sounds that warn of danger (a hooting car, a siren, a fire alarm or bell, a shout for help, a dog growling, thunder) and what to do: stop, move away, tell an adult. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G1.RUBRIC.2.1), never as a phone question: b) create sounds from objects for enjoyment.', '["what made this sound","is this a danger sound","what do you do when you hear it"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G1.RESOUR.WATER.WATER_SOURCES', 'ENVI.G1.RESOUR.WATER', 'environmental_activities', 1, 'Identify sources of water and record uses of water at home and school', ARRAY['ENVI.G1.RESOUR.WATER.a', 'ENVI.G1.RESOUR.WATER.b']::text[], 'Identifies sources of water in the immediate environment (rain, rivers, lakes, wells, boreholes, springs, taps, dams, tanks) and records uses at home and school (drinking, cooking, washing, bathing, cleaning, watering plants, giving animals, flushing toilets). Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G1.RUBRIC.3.1), never as a phone question: c) conserve water at home and school.', '["where does this water come from","what is water used for","match source and use"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G1.RESOUR.PLANTS.PLANT_PARTS', 'ENVI.G1.RESOUR.PLANTS', 'environmental_activities', 1, 'Identify the parts of a plant found in the school garden', ARRAY['ENVI.G1.RESOUR.PLANTS.a']::text[], 'Names and points to the parts of a plant: roots (under the soil), stem, leaves, flowers, and sometimes fruits and seeds, on real plants and pictures; knows the roots are hidden under the soil. Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G1.RUBRIC.3.1), never as a phone question: b) draw different parts of a plant found at school; c) carry out activities that conserve plants in the immediate environment.', '["name the part","point to the part","which part is under the soil"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENVI.G1.RESOUR.ANIMALS.DOMESTIC', 'ENVI.G1.RESOUR.ANIMALS', 'environmental_activities', 1, 'Identify domestic animals and those used as food in the locality', ARRAY['ENVI.G1.RESOUR.ANIMALS.a', 'ENVI.G1.RESOUR.ANIMALS.b']::text[], 'Identifies domestic animals (cows, goats, sheep, hens, ducks, rabbits, pigs, donkeys, dogs, cats, camels) and tells them from wild animals (lions, elephants, zebras), and lists domestic animals used as food in the locality (cows, goats, sheep, hens, rabbits, ducks, fish from ponds). Evidence rule: at least four of the last five fresh questions right across at least two question forms (read aloud to the child, with pictures), and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (ENVI.G1.RUBRIC.3.1), never as a phone question: c) carry out basic care activities for small domestic animals.', '["domestic or wild","which animal do we eat","odd one out"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
