INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G1.SOCIAL.OUR_HOME.HOME_CLEANING', 'ENVI.G1.SOCIAL.CLEANING_MY_BODY.BODY_CLEANING', 'skill', 'essential', 'Soap, water and a cloth clean the body and the home. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G1.SOCIAL.OUR_HOME.HOME_ACCIDENTS', 'ENVI.PP2.READINESS.SAFETY_RULES', 'skill', 'essential', 'Simple safety rules from pre-primary. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G1.SOCIAL.OUR_HOME.HOME_ACCIDENTS', 'ENVI.PP2.READINESS.HOME_PEOPLE_PLACES', 'skill', 'essential', 'Knowing the places in a home where accidents happen. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G1.SOCIAL.FAMILY_NEEDS.BASIC_NEEDS', 'ENVI.PP2.READINESS.HOME_PEOPLE_PLACES', 'skill', 'essential', 'Knowing the home and the people in it. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G1.SOCIAL.FAMILY_NEEDS.BASIC_NEEDS', 'ENVI.PP2.READINESS.SORT_THINGS', 'skill', 'essential', 'Sorting things into groups. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G1.SOCIAL.FAMILY_NEEDS.FOOD_SOURCES', 'ENVI.PP2.READINESS.FOODS_EATEN', 'skill', 'essential', 'Naming foods eaten at home. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G1.SOCIAL.FAMILY_NEEDS.FOOD_SOURCES', 'ENVI.G1.SOCIAL.FAMILY_NEEDS.BASIC_NEEDS', 'skill', 'essential', 'Food as a basic need of the family. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
