INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G1.SOCIAL.OUR_SCHOOL.HOME_SCHOOL_FEATURES', 'ENVI.PP2.READINESS.SENSES', 'skill', 'essential', 'Seeing and noticing things in the surroundings. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G1.SOCIAL.OUR_SCHOOL.WAY_SAFETY', 'ENVI.PP2.READINESS.SAFETY_RULES', 'skill', 'essential', 'Keeping away from roads and dangers. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
