INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G1.RESOUR.WATER.WATER_SOURCES', 'ENVI.G1.SOCIAL.CLEANING_MY_BODY.BODY_CLEANING', 'skill', 'essential', 'Water is used to wash the body. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
