INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENVI.G1.RESOUR.ANIMALS.DOMESTIC', 'ENVI.PP2.READINESS.SORT_THINGS', 'skill', 'essential', 'Sorting animals into groups. Proposed, to confirm by a CBC Environmental Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.CLEANING_MY_BODY.BODY_CLEANING.M_E1_BODY_WATER_HANDS', 'ENVI.G1.SOCIAL.CLEANING_MY_BODY.BODY_CLEANING', 'Thinks rinsing hands in water without soap makes them clean.', '{"question":"What do you need to wash your hands well?","wrong_answer":"Only water","correct_answer":"Water and soap"}'::jsonb, 'Water makes hands look and feel clean.', 'Offer "Only water" beside "Water and soap" and ask the child to choose.', 'Rub a little oil or charcoal on hands. Rinse with water, then use soap. Compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.CLEANING_MY_BODY.BODY_CLEANING.M_E1_BODY_TOWEL_TEETH', 'ENVI.G1.SOCIAL.CLEANING_MY_BODY.BODY_CLEANING', 'Picks a towel or comb as the material for cleaning teeth.', '{"question":"What do we clean our teeth with?","wrong_answer":"A comb","correct_answer":"A toothbrush (or a chewing stick)"}'::jsonb, 'All personal cleaning things are kept together, so the child mixes their uses.', 'Offer "A comb" beside "A toothbrush (or a chewing stick)" and ask the child to choose.', 'Match real items to a drawing of a face: comb to hair, toothbrush to teeth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.CLEANING_MY_BODY.BODY_CLEANING.M_E1_BODY_FEET_NO', 'ENVI.G1.SOCIAL.CLEANING_MY_BODY.BODY_CLEANING', 'Thinks feet do not need washing because they are not seen.', '{"question":"Should we wash our feet?","wrong_answer":"No, nobody sees them","correct_answer":"Yes, every day"}'::jsonb, 'The child links cleaning with what other people see.', 'Offer "No, nobody sees them" beside "Yes, every day" and ask the child to choose.', 'Look at feet after play. Say: feet get dirty and can smell or get jiggers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.CLEANING_MY_BODY.BODY_CLEANING.M_E1_BODY_HAIR_WATER', 'ENVI.G1.SOCIAL.CLEANING_MY_BODY.BODY_CLEANING', 'Thinks hair is cleaned by combing only, never washed.', '{"question":"How do we clean our hair?","wrong_answer":"Only comb it","correct_answer":"Wash it with water and soap, then comb it"}'::jsonb, 'Combing is done every day, washing less often.', 'Offer "Only comb it" beside "Wash it with water and soap, then comb it" and ask the child to choose.', 'Show a step chart: wash, rinse, dry, comb.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_HOME.HOME_CLEANING.M_E1_HOME_BROOM_WIPE', 'ENVI.G1.SOCIAL.OUR_HOME.HOME_CLEANING', 'Thinks a broom is used to wipe the table.', '{"question":"What do we use to wipe a table?","wrong_answer":"A broom","correct_answer":"A cloth"}'::jsonb, 'The broom is the cleaning tool the child sees most.', 'Offer "A broom" beside "A cloth" and ask the child to choose.', 'Act out each job with the right tool: sweep with a broom, wipe with a cloth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_HOME.HOME_CLEANING.M_E1_HOME_LITTER_CORNER', 'ENVI.G1.SOCIAL.OUR_HOME.HOME_CLEANING', 'Thinks litter swept up can be left in a corner.', '{"question":"Where does swept litter go?","wrong_answer":"In a corner","correct_answer":"Into a dustpan, then the bin or litter pit"}'::jsonb, 'Sweeping it away seems to finish the job.', 'Offer "In a corner" beside "Into a dustpan, then the bin or litter pit" and ask the child to choose.', 'Sweep, collect with a dustpan, put it in the bin. Say all three steps.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_HOME.HOME_CLEANING.M_E1_HOME_MOP_DRY', 'ENVI.G1.SOCIAL.OUR_HOME.HOME_CLEANING', 'Thinks a mop is used dry like a broom.', '{"question":"What do we put on a mop to clean the floor?","wrong_answer":"Nothing","correct_answer":"Water (and soap)"}'::jsonb, 'Mops and brooms both have long handles.', 'Offer "Nothing" beside "Water (and soap)" and ask the child to choose.', 'Show a mop dipped in a bucket of water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_HOME.HOME_CLEANING.M_E1_HOME_ADULT_ONLY', 'ENVI.G1.SOCIAL.OUR_HOME.HOME_CLEANING', 'Thinks cleaning the home is only for mothers or adults.', '{"question":"Who can help keep the home clean?","wrong_answer":"Only mother","correct_answer":"Everyone in the family, children too"}'::jsonb, 'At home, cleaning is often done by one adult.', 'Offer "Only mother" beside "Everyone in the family, children too" and ask the child to choose.', 'List small jobs a six-year-old can do: pick litter, wipe a table, arrange shoes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_HOME.HOME_ACCIDENTS.M_E1_ACC_MEDICINE_SWEET', 'ENVI.G1.SOCIAL.OUR_HOME.HOME_ACCIDENTS', 'Thinks coloured tablets or syrup are sweets.', '{"question":"You find coloured tablets on the table. What do you do?","wrong_answer":"Eat them, they look like sweets","correct_answer":"Do not touch; tell an adult"}'::jsonb, 'Many medicines look and taste like sweets.', 'Offer "Eat them, they look like sweets" beside "Do not touch; tell an adult" and ask the child to choose.', 'Show a medicine bottle and sweets. Rule: only take medicine from a parent or nurse.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_HOME.HOME_ACCIDENTS.M_E1_ACC_PARAFFIN_WATER', 'ENVI.G1.SOCIAL.OUR_HOME.HOME_ACCIDENTS', 'Thinks a bottle of paraffin or chemical in a soda bottle is a drink.', '{"question":"There is a soda bottle with a clear liquid on the floor. Can you drink it?","wrong_answer":"Yes, it is water","correct_answer":"No, it may be paraffin or poison; tell an adult"}'::jsonb, 'Things in soda bottles are usually drinks.', 'Offer "Yes, it is water" beside "No, it may be paraffin or poison; tell an adult" and ask the child to choose.', 'Smell (from a distance, adult-held) paraffin in a bottle. Rule: never drink from an unknown bottle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_HOME.HOME_ACCIDENTS.M_E1_ACC_JIKO_TOUCH', 'ENVI.G1.SOCIAL.OUR_HOME.HOME_ACCIDENTS', 'Thinks a jiko is safe to touch when the fire looks out.', '{"question":"The jiko has no flames. Is it safe to touch?","wrong_answer":"Yes, the fire is out","correct_answer":"No, it can still be very hot"}'::jsonb, 'No flames looks like no heat.', 'Offer "Yes, the fire is out" beside "No, it can still be very hot" and ask the child to choose.', 'Hold a hand near (not on) a jiko after cooking with an adult. Feel the heat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_HOME.HOME_ACCIDENTS.M_E1_ACC_SOCKET_PLAY', 'ENVI.G1.SOCIAL.OUR_HOME.HOME_ACCIDENTS', 'Thinks putting a finger or a stick into a socket is a game.', '{"question":"Is it safe to put a pin in a socket?","wrong_answer":"Yes, it is fun","correct_answer":"No, you can get an electric shock"}'::jsonb, 'A socket looks like a small toy with holes.', 'Offer "Yes, it is fun" beside "No, you can get an electric shock" and ask the child to choose.', 'Show a socket picture with a red cross. Electricity can hurt badly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.FAMILY_NEEDS.BASIC_NEEDS.M_E1_NEED_TOY', 'ENVI.G1.SOCIAL.FAMILY_NEEDS.BASIC_NEEDS', 'Calls a toy or a sweet a basic need.', '{"question":"Is a toy car a basic need?","wrong_answer":"Yes","correct_answer":"No, food, water, clothes and shelter are basic needs"}'::jsonb, 'Things the child loves feel necessary.', 'Offer "Yes" beside "No, food, water, clothes and shelter are basic needs" and ask the child to choose.', 'Ask: could we live without it? Sort pictures into "we must have" and "nice to have".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.FAMILY_NEEDS.BASIC_NEEDS.M_E1_NEED_HOUSE_SHAPE', 'ENVI.G1.SOCIAL.FAMILY_NEEDS.BASIC_NEEDS', 'Thinks only a stone or iron-roofed house is shelter, not a hut or a manyatta.', '{"question":"Is a grass-thatched hut a shelter?","wrong_answer":"No, a shelter is a stone house","correct_answer":"Yes, it keeps people safe and dry"}'::jsonb, 'Pictures of houses in books are often stone houses.', 'Offer "No, a shelter is a stone house" beside "Yes, it keeps people safe and dry" and ask the child to choose.', 'Show many shelters: a hut, a manyatta, a flat, a tent. Ask what each does.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.FAMILY_NEEDS.BASIC_NEEDS.M_E1_NEED_WATER_FOOD', 'ENVI.G1.SOCIAL.FAMILY_NEEDS.BASIC_NEEDS', 'Leaves out water as a need.', '{"question":"Name a basic need we drink.","wrong_answer":"Soda","correct_answer":"Water"}'::jsonb, 'Water is everywhere and not thought of as something we need.', 'Offer "Soda" beside "Water" and ask the child to choose.', 'Talk about a hot day with no water. Add water to the needs chart.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.FAMILY_NEEDS.BASIC_NEEDS.M_E1_NEED_SHOES_FOOD', 'ENVI.G1.SOCIAL.FAMILY_NEEDS.BASIC_NEEDS', 'Puts clothes and shoes in the food group when sorting.', '{"question":"Which group does a shirt go in: food, clothing or shelter?","wrong_answer":"Food","correct_answer":"Clothing"}'::jsonb, 'The child sorts by what he likes, not by kind.', 'Offer "Food" beside "Clothing" and ask the child to choose.', 'Use three baskets with picture labels: a plate, a shirt, a house.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.FAMILY_NEEDS.FOOD_SOURCES.M_E1_FOOD_EGG_PLANT', 'ENVI.G1.SOCIAL.FAMILY_NEEDS.FOOD_SOURCES', 'Thinks eggs or milk come from plants because they are bought in shops like flour.', '{"question":"Does milk come from a plant or an animal?","wrong_answer":"A plant","correct_answer":"An animal (a cow or goat)"}'::jsonb, 'The child sees milk in packets next to flour.', 'Offer "A plant" beside "An animal (a cow or goat)" and ask the child to choose.', 'Show pictures: a cow and milk, a hen and an egg, a maize plant and flour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.FAMILY_NEEDS.FOOD_SOURCES.M_E1_FOOD_BREAD_ANIMAL', 'ENVI.G1.SOCIAL.FAMILY_NEEDS.FOOD_SOURCES', 'Thinks bread or chapati comes from an animal.', '{"question":"Does a chapati come from a plant or an animal?","wrong_answer":"An animal","correct_answer":"A plant (wheat)"}'::jsonb, 'Bread is made, so its source is hidden.', 'Offer "An animal" beside "A plant (wheat)" and ask the child to choose.', 'Show wheat grains, flour and a chapati in order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.FAMILY_NEEDS.FOOD_SOURCES.M_E1_FOOD_SWEET_HEALTHY', 'ENVI.G1.SOCIAL.FAMILY_NEEDS.FOOD_SOURCES', 'Chooses sweets and soda as food for a healthy body because they give energy.', '{"question":"Which is better for a healthy body: an orange or a soda?","wrong_answer":"A soda","correct_answer":"An orange"}'::jsonb, 'Sweet things are given as treats and seem good.', 'Offer "A soda" beside "An orange" and ask the child to choose.', 'Show a tooth picture and a strong body picture. Fruit helps the body; too much sugar harms teeth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.FAMILY_NEEDS.FOOD_SOURCES.M_E1_FOOD_BIG_HEALTHY', 'ENVI.G1.SOCIAL.FAMILY_NEEDS.FOOD_SOURCES', 'Thinks the biggest plate of food is always the healthiest.', '{"question":"Which is healthier: a big plate of chips or a plate of githeri with sukuma?","wrong_answer":"The big plate of chips","correct_answer":"Githeri with sukuma"}'::jsonb, 'Being full feels like being healthy.', 'Offer "The big plate of chips" beside "Githeri with sukuma" and ask the child to choose.', 'Compare the two plates: count the kinds of food. Different foods keep us healthy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_SCHOOL.HOME_SCHOOL_FEATURES.M_E1_FEAT_ANIMALS', 'ENVI.G1.SOCIAL.OUR_SCHOOL.HOME_SCHOOL_FEATURES', 'Names animals or people seen on the way as features.', '{"question":"Which is a feature on the way to school: a bridge or a dog?","wrong_answer":"A dog","correct_answer":"A bridge"}'::jsonb, 'The child remembers what moved and caught attention.', 'Offer "A dog" beside "A bridge" and ask the child to choose.', 'Ask: will it be there tomorrow? Features stay in one place.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_SCHOOL.HOME_SCHOOL_FEATURES.M_E1_FEAT_INSIDE', 'ENVI.G1.SOCIAL.OUR_SCHOOL.HOME_SCHOOL_FEATURES', 'Names things inside the classroom (desks, a board) as features between home and school.', '{"question":"Is a desk a feature on the way between home and school?","wrong_answer":"Yes","correct_answer":"No, it is inside the class"}'::jsonb, 'The word school makes the child think of the classroom.', 'Offer "Yes" beside "No, it is inside the class" and ask the child to choose.', 'Draw a path from a house to a school. Only things along the path count.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_SCHOOL.HOME_SCHOOL_FEATURES.M_E1_FEAT_ROAD_NONE', 'ENVI.G1.SOCIAL.OUR_SCHOOL.HOME_SCHOOL_FEATURES', 'Does not count the road or path itself as a feature.', '{"question":"Is the road a feature?","wrong_answer":"No, it is just the way","correct_answer":"Yes, a road is a feature made by people"}'::jsonb, 'The road is where one walks, not something one sees.', 'Offer "No, it is just the way" beside "Yes, a road is a feature made by people" and ask the child to choose.', 'Point to the road on the drawing and name it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_SCHOOL.HOME_SCHOOL_FEATURES.M_E1_FEAT_ALL_SAME', 'ENVI.G1.SOCIAL.OUR_SCHOOL.HOME_SCHOOL_FEATURES', 'Thinks every child passes the same features to school.', '{"question":"Do all children pass the same things on the way to school?","wrong_answer":"Yes","correct_answer":"No, each child''s way is different"}'::jsonb, 'The child assumes others see what he sees.', 'Offer "Yes" beside "No, each child''s way is different" and ask the child to choose.', 'Let three children draw their way. Compare the features.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_SCHOOL.WAY_SAFETY.M_E1_WAY_STRANGER_GIFT', 'ENVI.G1.SOCIAL.OUR_SCHOOL.WAY_SAFETY', 'Thinks taking sweets from a friendly stranger is fine.', '{"question":"A stranger offers you sweets on the way home. What do you do?","wrong_answer":"Take them and say thank you","correct_answer":"Say no, walk away and tell a trusted adult"}'::jsonb, 'Children are taught to be polite and accept gifts.', 'Offer "Take them and say thank you" beside "Say no, walk away and tell a trusted adult" and ask the child to choose.', 'Role-play saying "No, thank you" and walking to a trusted adult.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_SCHOOL.WAY_SAFETY.M_E1_WAY_ROAD_PLAY', 'ENVI.G1.SOCIAL.OUR_SCHOOL.WAY_SAFETY', 'Thinks a quiet road is a safe place to play.', '{"question":"Is a quiet road a good place to play?","wrong_answer":"Yes, there are no cars now","correct_answer":"No, a car or motorbike can come suddenly"}'::jsonb, 'The child sees the road empty and forgets it changes.', 'Offer "Yes, there are no cars now" beside "No, a car or motorbike can come suddenly" and ask the child to choose.', 'Show how fast a boda boda comes round a bend. Play only in safe places.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_SCHOOL.WAY_SAFETY.M_E1_WAY_RUN_CROSS', 'ENVI.G1.SOCIAL.OUR_SCHOOL.WAY_SAFETY', 'Thinks running fast across the road is the safe way to cross.', '{"question":"How should you cross a road?","wrong_answer":"Run fast","correct_answer":"Stop, look both ways, and walk across when it is clear"}'::jsonb, 'Running feels like getting out of danger quickly.', 'Offer "Run fast" beside "Stop, look both ways, and walk across when it is clear" and ask the child to choose.', 'Practise on a chalk road: stop, look, listen, walk.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_SCHOOL.WAY_SAFETY.M_E1_WAY_ALONE_LATE', 'ENVI.G1.SOCIAL.OUR_SCHOOL.WAY_SAFETY', 'Thinks it is fine to stop and play on the way home and arrive late.', '{"question":"After school, what should you do?","wrong_answer":"Play on the way and go home later","correct_answer":"Go straight home"}'::jsonb, 'Playing with friends is more fun than going home.', 'Offer "Play on the way and go home later" beside "Go straight home" and ask the child to choose.', 'Talk about parents worrying and dangers after dark. Agree: go straight home.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_MARKET.MARKET_PEOPLE.M_E1_MKT_ONLY_SELLERS', 'ENVI.G1.SOCIAL.OUR_MARKET.MARKET_PEOPLE', 'Thinks only sellers are found in a market.', '{"question":"Name a person in a market who is not a seller.","wrong_answer":"There is none","correct_answer":"A buyer (a porter, a cleaner)"}'::jsonb, 'Stalls and sellers are what the child notices most.', 'Offer "There is none" beside "A buyer (a porter, a cleaner)" and ask the child to choose.', 'Act out a market with sellers, buyers, porters and a cleaner.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_MARKET.MARKET_PEOPLE.M_E1_MKT_PORTER_BUYER', 'ENVI.G1.SOCIAL.OUR_MARKET.MARKET_PEOPLE', 'Thinks a person carrying sacks is buying them.', '{"question":"A man carries sacks for a trader. What is his job?","wrong_answer":"He is buying the sacks","correct_answer":"He is a porter; he carries goods for others"}'::jsonb, 'Carrying goods looks like taking them home.', 'Offer "He is buying the sacks" beside "He is a porter; he carries goods for others" and ask the child to choose.', 'Show a porter being paid to carry. Name the job.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_MARKET.MARKET_PEOPLE.M_E1_MKT_BUYER_PAY', 'ENVI.G1.SOCIAL.OUR_MARKET.MARKET_PEOPLE', 'Thinks the seller pays the buyer.', '{"question":"Who gives the money when you buy tomatoes?","wrong_answer":"The seller","correct_answer":"The buyer"}'::jsonb, 'Children see change given back and think the seller pays.', 'Offer "The seller" beside "The buyer" and ask the child to choose.', 'Role-play with play money: the buyer pays, the seller gives the goods and change.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_MARKET.MARKET_PEOPLE.M_E1_MKT_FREE_FOOD', 'ENVI.G1.SOCIAL.OUR_MARKET.MARKET_PEOPLE', 'Thinks food in the market is free to take.', '{"question":"Can you take a banana from a market stall without paying?","wrong_answer":"Yes, it is there for everyone","correct_answer":"No, we must pay for it"}'::jsonb, 'Food at home is given without paying.', 'Offer "Yes, it is there for everyone" beside "No, we must pay for it" and ask the child to choose.', 'Role-play buying. Say: taking without paying is stealing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_MARKET.FRUIT_VEG.M_E1_FRUIT_SWEET_ONLY', 'ENVI.G1.SOCIAL.OUR_MARKET.FRUIT_VEG', 'Thinks a food is a fruit only if it is sweet, so an avocado is a vegetable.', '{"question":"Is an avocado a fruit or a vegetable?","wrong_answer":"A vegetable, it is not sweet","correct_answer":"A fruit"}'::jsonb, 'The child sorts by taste.', 'Offer "A vegetable, it is not sweet" beside "A fruit" and ask the child to choose.', 'Cut an avocado and a mango: both have a seed inside and grow on trees. Call both fruits as the class chart does.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_MARKET.FRUIT_VEG.M_E1_VEG_COOKED_ONLY', 'ENVI.G1.SOCIAL.OUR_MARKET.FRUIT_VEG', 'Thinks a vegetable is anything cooked, so cooked bananas are vegetables and raw carrots are not.', '{"question":"Is a carrot a vegetable?","wrong_answer":"No, we can eat it raw","correct_answer":"Yes, a carrot is a vegetable"}'::jsonb, 'At home vegetables are cooked with ugali.', 'Offer "No, we can eat it raw" beside "Yes, a carrot is a vegetable" and ask the child to choose.', 'Show raw and cooked carrots. It is still a carrot, still a vegetable.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_MARKET.FRUIT_VEG.M_E1_MKT_FOOD_NOT_MEAT', 'ENVI.G1.SOCIAL.OUR_MARKET.FRUIT_VEG', 'Thinks the market sells only fruits and vegetables, not meat, fish or eggs.', '{"question":"Name a food from an animal sold in the market.","wrong_answer":"There is none","correct_answer":"Fish (meat, eggs)"}'::jsonb, 'Stalls of fruits and vegetables are the most colourful.', 'Offer "There is none" beside "Fish (meat, eggs)" and ask the child to choose.', 'Show pictures of a butchery and a fish stall in a market.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.SOCIAL.OUR_MARKET.FRUIT_VEG.M_E1_FRUIT_COLOUR', 'ENVI.G1.SOCIAL.OUR_MARKET.FRUIT_VEG', 'Sorts by colour, so green sukuma goes with green oranges as fruit.', '{"question":"Is sukuma wiki a fruit or a vegetable?","wrong_answer":"A fruit, it is green like an orange","correct_answer":"A vegetable"}'::jsonb, 'Colour is the first thing children sort by.', 'Offer "A fruit, it is green like an orange" beside "A vegetable" and ask the child to choose.', 'Sort by what part we eat: leaves are vegetables; sweet or seeded parts from trees are fruits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.NATURA.WEATHER_AND_THE_SKY.SKY.M_E1_SKY_SUN_NIGHT', 'ENVI.G1.NATURA.WEATHER_AND_THE_SKY.SKY', 'Thinks the sun can be seen at night.', '{"question":"Can we see the sun at night?","wrong_answer":"Yes","correct_answer":"No, at night we see the moon and stars"}'::jsonb, 'The child mixes the sun and the moon, both round and bright.', 'Offer "Yes" beside "No, at night we see the moon and stars" and ask the child to choose.', 'Draw a day sky and a night sky side by side. Put the sun only in the day sky.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.NATURA.WEATHER_AND_THE_SKY.SKY.M_E1_SKY_STARS_GONE', 'ENVI.G1.NATURA.WEATHER_AND_THE_SKY.SKY', 'Thinks the stars go away in the day.', '{"question":"Where are the stars during the day?","wrong_answer":"They go away","correct_answer":"They are still there, but the sun is too bright for us to see them"}'::jsonb, 'What cannot be seen seems to be gone.', 'Offer "They go away" beside "They are still there, but the sun is too bright for us to see them" and ask the child to choose.', 'Shine a small torch in a bright room and a dark room. Seen only in the dark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.NATURA.WEATHER_AND_THE_SKY.SKY.M_E1_SKY_MOON_DAY', 'ENVI.G1.NATURA.WEATHER_AND_THE_SKY.SKY', 'Thinks the moon is never seen during the day.', '{"question":"Can you sometimes see the moon in the day?","wrong_answer":"No, never","correct_answer":"Yes, sometimes"}'::jsonb, 'The moon is taught as the night object.', 'Offer "No, never" beside "Yes, sometimes" and ask the child to choose.', 'Look out on a morning when the moon shows, or show a photo of a day moon.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.NATURA.WEATHER_AND_THE_SKY.SKY.M_E1_SKY_CLOUDS_NIGHT', 'ENVI.G1.NATURA.WEATHER_AND_THE_SKY.SKY', 'Thinks there are no clouds at night.', '{"question":"Can there be clouds at night?","wrong_answer":"No","correct_answer":"Yes, clouds can cover the moon and stars"}'::jsonb, 'Clouds are hard to see in the dark.', 'Offer "No" beside "Yes, clouds can cover the moon and stars" and ask the child to choose.', 'Talk about a night when the moon was hidden. Clouds covered it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.NATURA.WEATHER_AND_THE_SKY.WEATHER_KINDS.M_E1_WEA_CLOUD_RAIN', 'ENVI.G1.NATURA.WEATHER_AND_THE_SKY.WEATHER_KINDS', 'Thinks a cloudy day is the same as a rainy day.', '{"question":"The sky is full of grey clouds but no rain falls. What is the weather?","wrong_answer":"Rainy","correct_answer":"Cloudy"}'::jsonb, 'Clouds and rain often come together.', 'Offer "Rainy" beside "Cloudy" and ask the child to choose.', 'Show two pictures: clouds only, clouds with rain falling. Name each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.NATURA.WEATHER_AND_THE_SKY.WEATHER_KINDS.M_E1_WEA_WIND_SEE', 'ENVI.G1.NATURA.WEATHER_AND_THE_SKY.WEATHER_KINDS', 'Thinks wind cannot be a weather condition because it cannot be seen.', '{"question":"How do you know it is windy?","wrong_answer":"You cannot know","correct_answer":"Trees move, leaves blow and clothes on the line wave"}'::jsonb, 'Weather words the child knows are things seen.', 'Offer "You cannot know" beside "Trees move, leaves blow and clothes on the line wave" and ask the child to choose.', 'Take a paper streamer outside. Watch it move.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.NATURA.WEATHER_AND_THE_SKY.WEATHER_KINDS.M_E1_WEA_SUN_HOT', 'ENVI.G1.NATURA.WEATHER_AND_THE_SKY.WEATHER_KINDS', 'Thinks a sunny day is always hot, and a cold day cannot be sunny.', '{"question":"Can a sunny morning be cold?","wrong_answer":"No, sun is always hot","correct_answer":"Yes, some sunny mornings are cold"}'::jsonb, 'Sunny and hot are taught together.', 'Offer "No, sun is always hot" beside "Yes, some sunny mornings are cold" and ask the child to choose.', 'Talk about a cold, bright morning in July. Feel the air.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.NATURA.WEATHER_AND_THE_SKY.WEATHER_KINDS.M_E1_WEA_CLOTHES', 'ENVI.G1.NATURA.WEATHER_AND_THE_SKY.WEATHER_KINDS', 'Picks the wrong clothing for the weather (a sweater on a hot day).', '{"question":"It is very hot. What should you wear?","wrong_answer":"A thick sweater","correct_answer":"Light clothes and a hat"}'::jsonb, 'The child picks favourite clothes, not weather clothes.', 'Offer "A thick sweater" beside "Light clothes and a hat" and ask the child to choose.', 'Dress a paper doll for each weather card.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.NATURA.SOIL.SOIL_PLAY.M_E1_SOIL_DIRTY_BAD', 'ENVI.G1.NATURA.SOIL.SOIL_PLAY', 'Thinks playing with soil is always bad because it makes one dirty.', '{"question":"Is it good to play with soil?","wrong_answer":"No, it makes us dirty","correct_answer":"Yes, it is fun, and we wash our hands after"}'::jsonb, 'Children are scolded for getting dirty.', 'Offer "No, it makes us dirty" beside "Yes, it is fun, and we wash our hands after" and ask the child to choose.', 'Play with soil in class, then wash hands together. Say: play, then wash.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.NATURA.SOIL.SOIL_PLAY.M_E1_SOIL_EAT', 'ENVI.G1.NATURA.SOIL.SOIL_PLAY', 'Thinks tasting soil is part of playing.', '{"question":"Can we eat soil while playing?","wrong_answer":"Yes, a little","correct_answer":"No, never eat soil"}'::jsonb, 'Young children put things in their mouths.', 'Offer "Yes, a little" beside "No, never eat soil" and ask the child to choose.', 'Show a picture of germs and worms in soil. Rule: soil never goes in the mouth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.NATURA.SOIL.SOIL_PLAY.M_E1_SOIL_WASH_NONE', 'ENVI.G1.NATURA.SOIL.SOIL_PLAY', 'Thinks hands need no washing if the soil was dry.', '{"question":"You played with dry soil. Should you wash your hands?","wrong_answer":"No, it was dry","correct_answer":"Yes, always wash with soap"}'::jsonb, 'Dry soil falls off, so hands look clean.', 'Offer "No, it was dry" beside "Yes, always wash with soap" and ask the child to choose.', 'Rub hands after dry soil play on white paper. See the dust.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.NATURA.SOIL.SOIL_PLAY.M_E1_SOIL_THROW', 'ENVI.G1.NATURA.SOIL.SOIL_PLAY', 'Thinks throwing soil at friends is a fun way to play.', '{"question":"Is throwing soil at a friend a good way to play?","wrong_answer":"Yes, it is fun","correct_answer":"No, it can hurt their eyes"}'::jsonb, 'Throwing is part of many games.', 'Offer "Yes, it is fun" beside "No, it can hurt their eyes" and ask the child to choose.', 'Talk about soil in the eyes. Agree games where soil stays on the ground.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.NATURA.SOUND.SOUNDS.M_E1_SND_LOUD_DANGER', 'ENVI.G1.NATURA.SOUND.SOUNDS', 'Thinks every loud sound is a danger sound, and soft sounds are always safe.', '{"question":"Is a loud song at a party a danger sound?","wrong_answer":"Yes, it is loud","correct_answer":"No, a hooting car or a fire alarm warns of danger"}'::jsonb, 'Loud sounds are frightening, so they seem dangerous.', 'Offer "Yes, it is loud" beside "No, a hooting car or a fire alarm warns of danger" and ask the child to choose.', 'Play a loud song and a car hoot. Ask which one tells us to move.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.NATURA.SOUND.SOUNDS.M_E1_SND_HOOT_IGNORE', 'ENVI.G1.NATURA.SOUND.SOUNDS', 'Thinks a car hooting is just noise and keeps walking on the road.', '{"question":"You hear a car hooting behind you on the road. What do you do?","wrong_answer":"Keep walking in the road","correct_answer":"Move to the side of the road at once"}'::jsonb, 'Hooting is heard so often it seems to mean nothing.', 'Offer "Keep walking in the road" beside "Move to the side of the road at once" and ask the child to choose.', 'Play the sound and practise stepping to the side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.NATURA.SOUND.SOUNDS.M_E1_SND_ANIMAL_MIX', 'ENVI.G1.NATURA.SOUND.SOUNDS', 'Matches a sound to the wrong animal (a goat for a cow''s moo).', '{"question":"Which animal says \"moo\"?","wrong_answer":"A goat","correct_answer":"A cow"}'::jsonb, 'Farm animals are learnt together.', 'Offer "A goat" beside "A cow" and ask the child to choose.', 'Play animal sounds and match to pictures.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.NATURA.SOUND.SOUNDS.M_E1_SND_ALARM_HIDE', 'ENVI.G1.NATURA.SOUND.SOUNDS', 'Thinks the right thing at a fire alarm is to hide under the desk.', '{"question":"The school fire bell rings. What do you do?","wrong_answer":"Hide under the desk","correct_answer":"Leave the class calmly with the teacher to the assembly point"}'::jsonb, 'Hiding feels safe when frightened.', 'Offer "Hide under the desk" beside "Leave the class calmly with the teacher to the assembly point" and ask the child to choose.', 'Hold a fire drill. Walk out in a line to the assembly point.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.RESOUR.WATER.WATER_SOURCES.M_E1_WAT_TAP_SOURCE', 'ENVI.G1.RESOUR.WATER.WATER_SOURCES', 'Thinks water is made in the tap.', '{"question":"Where does tap water come from?","wrong_answer":"The tap makes it","correct_answer":"From a river, borehole or tank through pipes"}'::jsonb, 'The tap is where water is seen to appear.', 'Offer "The tap makes it" beside "From a river, borehole or tank through pipes" and ask the child to choose.', 'Follow a pipe from the tap to a tank in the school.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.RESOUR.WATER.WATER_SOURCES.M_E1_WAT_RAIN_NONE', 'ENVI.G1.RESOUR.WATER.WATER_SOURCES', 'Does not see rain as a source of water.', '{"question":"Is rain a source of water?","wrong_answer":"No, rain just falls","correct_answer":"Yes, we can collect rain in tanks and pots"}'::jsonb, 'Rain is weather, not a water supply, to the child.', 'Offer "No, rain just falls" beside "Yes, we can collect rain in tanks and pots" and ask the child to choose.', 'Put a bucket under the roof when it rains. See the water collected.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.RESOUR.WATER.WATER_SOURCES.M_E1_WAT_USE_DRINK', 'ENVI.G1.RESOUR.WATER.WATER_SOURCES', 'Names drinking as the only use of water.', '{"question":"Name another use of water apart from drinking.","wrong_answer":"There is none","correct_answer":"Cooking (washing, bathing, cleaning)"}'::jsonb, 'Drinking is the use the child feels most.', 'Offer "There is none" beside "Cooking (washing, bathing, cleaning)" and ask the child to choose.', 'List with the class everything water did for them today.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.RESOUR.WATER.WATER_SOURCES.M_E1_WAT_SEA_ALL', 'ENVI.G1.RESOUR.WATER.WATER_SOURCES', 'Thinks all water sources are big like rivers and lakes, missing wells and springs.', '{"question":"Is a well a source of water?","wrong_answer":"No, sources are rivers and lakes","correct_answer":"Yes"}'::jsonb, 'Big water bodies are shown in books.', 'Offer "No, sources are rivers and lakes" beside "Yes" and ask the child to choose.', 'Show a picture of a well and a spring near a village.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.RESOUR.PLANTS.PLANT_PARTS.M_E1_PART_ROOTS_NONE', 'ENVI.G1.RESOUR.PLANTS.PLANT_PARTS', 'Thinks a plant has no roots because they cannot be seen.', '{"question":"Does a plant have roots?","wrong_answer":"No","correct_answer":"Yes, under the soil"}'::jsonb, 'Children name only what they see above the ground.', 'Offer "No" beside "Yes, under the soil" and ask the child to choose.', 'Gently pull up a weed. Show the roots.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.RESOUR.PLANTS.PLANT_PARTS.M_E1_PART_STEM_ROOT', 'ENVI.G1.RESOUR.PLANTS.PLANT_PARTS', 'Calls the stem the root because it goes into the soil.', '{"question":"What is the part that holds up the leaves called?","wrong_answer":"The root","correct_answer":"The stem"}'::jsonb, 'The stem touches the soil, so it seems to be the root.', 'Offer "The root" beside "The stem" and ask the child to choose.', 'Use a pulled-up plant: green stem above, roots below.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.RESOUR.PLANTS.PLANT_PARTS.M_E1_PART_FLOWER_ALL', 'ENVI.G1.RESOUR.PLANTS.PLANT_PARTS', 'Thinks a plant without flowers now is not a plant.', '{"question":"Grass has no flowers today. Is grass a plant?","wrong_answer":"No, it has no flowers","correct_answer":"Yes, it has roots, a stem and leaves"}'::jsonb, 'Plants in songs and pictures always have flowers.', 'Offer "No, it has no flowers" beside "Yes, it has roots, a stem and leaves" and ask the child to choose.', 'Walk and find plants with and without flowers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.RESOUR.PLANTS.PLANT_PARTS.M_E1_PART_TREE_NOT', 'ENVI.G1.RESOUR.PLANTS.PLANT_PARTS', 'Thinks a tree is not a plant because it is too big.', '{"question":"Is a mango tree a plant?","wrong_answer":"No, it is a tree","correct_answer":"Yes, a tree is a big plant"}'::jsonb, 'Plant is the word for small garden plants.', 'Offer "No, it is a tree" beside "Yes, a tree is a big plant" and ask the child to choose.', 'Compare a bean plant and a tree: both have roots, stem, leaves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.RESOUR.ANIMALS.DOMESTIC.M_E1_DOM_WILD_ZOO', 'ENVI.G1.RESOUR.ANIMALS.DOMESTIC', 'Thinks a zebra or lion is domestic because people go to see it in a park.', '{"question":"Is a zebra a domestic animal?","wrong_answer":"Yes","correct_answer":"No, it is a wild animal"}'::jsonb, 'Animals seen near people at parks seem tame.', 'Offer "Yes" beside "No, it is a wild animal" and ask the child to choose.', 'Sort pictures: animals kept at home and animals living in the wild.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.RESOUR.ANIMALS.DOMESTIC.M_E1_DOM_DOG_FOOD', 'ENVI.G1.RESOUR.ANIMALS.DOMESTIC', 'Lists a dog or a cat as an animal used as food.', '{"question":"Which animal is kept as food: a hen or a dog?","wrong_answer":"A dog","correct_answer":"A hen"}'::jsonb, 'All home animals are grouped together.', 'Offer "A dog" beside "A hen" and ask the child to choose.', 'Ask what each home animal gives us. Dogs guard; hens give eggs and meat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.RESOUR.ANIMALS.DOMESTIC.M_E1_DOM_BIRD_NOT', 'ENVI.G1.RESOUR.ANIMALS.DOMESTIC', 'Thinks hens and ducks are not animals because they are birds.', '{"question":"Is a hen an animal?","wrong_answer":"No, it is a bird","correct_answer":"Yes, a hen is a domestic animal (a bird)"}'::jsonb, 'Animal is used at home for four-legged animals.', 'Offer "No, it is a bird" beside "Yes, a hen is a domestic animal (a bird)" and ask the child to choose.', 'Show that birds are animals too: they move, eat and breathe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENVI.G1.RESOUR.ANIMALS.DOMESTIC.M_E1_DOM_ALL_FOOD', 'ENVI.G1.RESOUR.ANIMALS.DOMESTIC', 'Thinks every domestic animal is kept for food.', '{"question":"Is a donkey kept for food in most homes?","wrong_answer":"Yes","correct_answer":"No, a donkey carries loads"}'::jsonb, 'Talk of animals at home is mostly about meat and milk.', 'Offer "Yes" beside "No, a donkey carries loads" and ask the child to choose.', 'Make a chart: animal and what it does for us.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
